{
  "recipe_name": "Puffy Tacos Texas Style",
  "instructions": [
    {
      "text": "Mix fresh masa or masa harina corn flour with the fajita seasoning."
    },
    {
      "text": "Add the warm water to form a soft dough."
    },
    {
      "text": "Knead by hand about 5 minutes."
    },
    {
      "text": "If the mixture seems too crumbly, add more water a little at a time."
    },
    {
      "text": "If the dough sticks to your hand, it is too wet and you will need to add a little more masa."
    },
    {
      "text": "When the dough feels just right- not too wet and not too crumbly, then put into a plastic bag, seal, and let rest for 15 minutes."
    },
    {
      "text": "Pinch off a piece of the dough about 1-1/2 inches and form into a smooth ball with the palms of your hands."
    },
    {
      "text": "Open the tortilla press and lay a piece of plastic wrap on the bottom half."
    },
    {
      "text": "Next, place a single ball of dough on the plastic in the center and place another piece of plastic wrap (or sandwich bag) on top of the ball and flatten slightly with your hand."
    },
    {
      "text": "Close the press firmly, then open."
    },
    {
      "text": "Dampen your hands with a little water and peel the top bag off the tortilla, then lift the bottom plastic bag up with the tortilla still on it."
    },
    {
      "text": "Transfer the tortilla, dough side down, to your dampened hand."
    },
    {
      "text": "With your free hand, carefully peel the bag off the dough."
    },
    {
      "text": "Carefully place the tortilla that is approximately 1/8 inch thick into the hot oil."
    },
    {
      "text": "Let cook about 30 seconds then with a slotted metal spatula carefully turn over and cook for another 1-2 minutes."
    },
    {
      "text": "After turning the tortilla over, take the slotted metal spoon and gently start to push in the center of the tortilla downward to form a \"V\"."
    },
    {
      "text": "Do this very gently or the tortilla will try to break in half."
    },
    {
      "text": "The tortilla should start to puff so try to keep submerged under the hot oil."
    },
    {
      "text": "Let fry for a about 1 minute, but not until completely crisp."
    },
    {
      "text": "Remove and drain on paper towels."
    },
    {
      "text": "Fill with your favorites including refried beans, chicken, beef, fajitas, ground beef, and top with lettuce, tomato, onion, avocado and grated cheese and top with your favorite salsa."
    }
  ],
  "ingredients": [
    {
