{
  "recipe_name" : "Homemade Paneer (Fresh Indian Cheese)",
  "instructions":[
    {
        "text": "Pour the milk into a large thick bottomed stockpot and bring the milk to a rolling boil on medium-high heat while constantly stirring with a large wooden spoon or Silicone spatula."
    },
    {
        "text": "Once the milk starts to boil, pour in half of the lemon juice and stir. The milk will start to curdle. If the whey (the watery liquid that separates from the solid cheese curds) still looks slightly milky, add a little more lemon juice."
    },
    {
        "text": "The whey will be slightly yellowish-green in color while the cheese curds will separate and float to the top."
    },
    {
        "text": "Remove the pot from the stove and drain the contents into a colander or sieve lined with a clean piece of dampened kitchen cloth or a few layers of cheesecloth placed over a large bowl or pot."
    },
    {
        "text": "Discard the whey that collects in the bowl and wash the curds by running cold tap water over the cheese in the cloth."
    },
    {
        "text": "Wash at least 3 times to get rid of any residual lemon juice that might be trapped in the cheese curds."
    },
    {
        "text": "Once this is done, tie the ends of the cheesecloth/kitchen cloth and squeeze to release any extra liquid out of the cheese."
    },
    {
        "text": "The cheese/paneer inside the cheesecloth will be appear to resemble crumbs."
    },
    {
        "text": "To set the paneer into a more firm cake, place a large heavy pot filled with water over the cheesecloth containing the paneer and let it sit for one hour at room temperature on a flat surface."
    },
    {
        "text": "The weight will help pack the paneer into a tight and firm structure."
    },
    {
        "text": "Unwrap the cheesecloth and cut the paneer into 1- by 1 1/2-inch rectangles (or any shape or size you like) and store in the refrigerator in an airtight container for up to a week."
    },
    {
        "text": "You can also freeze the paneer for long-term storage by wrapping it in plastic wrap and then storing it in an airtight plastic bag."
    }
  ],
  "ingredients": [
    {
      "name": "milk",
      "preparation": "boiled",
      "amount": "1 gallon",
      "weight": "3785.4"
    },
    {
      "name": "lemon juice",
      "preparation": "raw",
      "amount": "1/2 cup",
      "weight": "118.3"
    }
  ]
}

