{
  "recipe_name": "Wonton Skin Raviolis",
  "instructions": [
    {
      "text": "Lay out 8 wonton wrappers on counter in front of you."
    },
    {
      "text": "Paint each one lightly with beaten egg."
    },
    {
      "text": "Place 1 tablespoon filling in the center of each ravioli."
    },
    {
      "text": "Seal by placing 8 additional wonton wrappers on top to cover each square."
    },
    {
      "text": "Pick up each ravioli and press well all around edges to seal."
    },
    {
      "text": "For a good seal, make sure no filling is stuck in the edges."
    },
    {
      "text": "Square ravioli can be left as is or cut into festive shapes (stars, hearts etc.) with a medium cookie cutter."
    },
    {
      "text": "Place the ravioli upside down on a cookie sheet lined with parchment."
    },
    {
      "text": "Lay out 8 more wrappers and repeat the process until either wrappers or filling is gone."
    },
    {
      "text": "Lay additional parchment or plastic wrap between layers of ravioli as needed as you lay them on the cookie sheet."
    },
    {
      "text": "The entire cookie sheet can be wrapped well and refrigerated for 1 to 2 days."
    },
    {
      "text": "When ready to cook ravioli, bring large pot of salted water to a boil."
    },
    {
      "text": "Lower heat to a simmer, give the water a good stir to form a whirlpool effect and quickly drop in 12 to 15 raviolis one by one, stirring gently to separate them as they hit the water."
    },
    {
      "text": "Poach gently 2 to 3 minutes, or until ravioli puff up, float to the surface and are opaque in the center (in the case of raw poultry or fish fillings) Remove ravioli from pot with a slotted spoon and reserve."
    },
    {
      "text": "Cook remaining ravioli in same manner."
    },
    {
      "text": "Serve with sauce, butter, or oil, or in broth, and with or without cheese."
    }
  ],
