{
  "recipe_name" : "Chinese White Rice",
  "instructions":[
    {
        "text": "Pour desired amount of rice into a pot with a good fitting lid (rice must cover bottom of pan and should be an inch or more deep, so use the proper sized pot for amount of rice you are cooking)."
    },
    {
        "text": "Cover rice several inches with water."
    },
    {
        "text": "Stir rice and water with your hand. Water will turn milky (this is the extra starch coming off the rice)."
    },
    {
        "text": "Pour water off the rice using your hand or the lid to keep rice in the pot."
    },
    {
        "text": "Repeat rinsing and draining two more times. Water should be clear on last rinse."
    },
    {
        "text": "Cover rice with clean cold water to the depth of your first knuckle with the tip of your pointer finger touching the top of the rice (this will be a bit less than an inch)."
    },
    {
        "text": "Put pot on stove and turn burner to high."
    },
    {
        "text": "Bring to a boil, uncovered, and continue boiling until tunnels form from the steam coming through the rice - most of the water will no longer be visible."
    },
    {
        "text": "Cover pot with lid and turn stove down to low."
    },
    {
        "text": "Keep covered and cook for 30 minutes more."
    },
    {
        "text": "Uncover and fluff up a few grains to test to see if it's done."
    },
    {
        "text": "If necessary, cover and cook for a few more minutes."
    },
    {
        "text": "When done, fluff rice with fork and serve."
    },
    {
        "text": "If you're making fried rice, it's best to use day old rice so put this in the fridge after it has cooled a bit and enjoy it tomorrow!"
    }
  ],
  "ingredients": [
    {
      "name": "white rice",
      "preparation": "raw",
      "amount": "2 cups",
      "weight": "200 grams"
    },
    {
      "name": "water",
      "preparation": "none",
      "amount": "enough to cover rice",
      "weight": "200 grams"
    }
  ]
}

