{
  "recipe_name" : "Hungarian Country Bread",
  "instructions":[
    {
        "text": "Dissolve yeast in water (if using dry yeast, follow instructions)."
    },
    {
        "text": "Add most of the flour and the salt."
    },
    {
        "text": "Knead vigorously by hand for 5-10 minutes."
    },
    {
        "text": "Let rise, covered, to double size (1-2 hours)."
    },
    {
        "text": "Heat the oven to 450 deg F/ 230 deg C."
    },
    {
        "text": "Knead again, vigorously, for 5 minutes."
    },
    {
        "text": "Shape one big, round loaf and put on a greased baking tray."
    },
    {
        "text": "Cover and let rise for another 45 minutes."
    },
    {
        "text": "Make a few cuts in the loaf with a razorblade."
    },
    {
        "text": "Bake in the oven for 10 minutes."
    },
    {
        "text": "Reduce heat to 400/200 deg and bake another one hour."
    },
    {
        "text": "The crust should become quite brown."
    },
    {
        "text": "Turn off the oven, take out the bread, and brush the bread with water."
    },
    {
        "text": "Put it back in the oven for 15 minutes."
    },
    {
        "text": "Let cool uncovered."
    }
  ],
